from solution import odd_Equivalent


def test_issue_example_given():
    """Count of rotations with odd value is 3 for '011001'."""
    assert odd_Equivalent("011001", 6) == 3  # 3 ones in "011001" => 3


def test_issue_all_zeros():
    """Count of rotations with odd value is 0 when no '1's."""
    assert odd_Equivalent("0000", 4) == 0  # 0 ones => 0


def test_issue_all_ones():
    """Count of rotations with odd value equals length when all '1's."""
    assert odd_Equivalent("111", 3) == 3  # 3 ones => 3


def test_issue_single_zero():
    """Count of rotations with odd value is 0 for '0'."""
    assert odd_Equivalent("0", 1) == 0  # 0 ones => 0


def test_issue_single_one():
    """Count of rotations with odd value is 1 for '1'."""
    assert odd_Equivalent("1", 1) == 1  # 1 one => 1


def test_issue_two_char_mixed():
    """Count of rotations with odd value is 1 for '01'."""
    assert odd_Equivalent("01", 2) == 1  # 1 one => 1


def test_issue_single_one_among_zeros():
    """Count of rotations with odd value is 1 for '0001'."""
    assert odd_Equivalent("0001", 4) == 1  # 1 one => 1


def test_issue_alternating():
    """Count of rotations with odd value is 2 for '1010'."""
    assert odd_Equivalent("1010", 4) == 2  # 2 ones => 2


def test_issue_empty_string():
    """Count of rotations with odd value is 0 for empty string."""
    assert odd_Equivalent("", 0) == 0  # 0 ones => 0


def test_contract_matches_number_of_ones():
    """Contract: count must equal number of '1's ending rotations."""
    assert odd_Equivalent("10111", 5) == 4  # 4 ones => 4


def test_contract_rotation_invariance():
    """Contract: rotated inputs must give same odd-rotation count."""
    assert odd_Equivalent("1000", 4) == odd_Equivalent("0001", 4) == 1  # 1 one => 1
